use super::*;

/// The current branch, or `None` for a detached HEAD.
pub fn current_branch(tree: &Path) -> Option<String> {
    match git(tree, &["rev-parse", "--abbrev-ref", "HEAD"]) {
        Ok(b) if b == "HEAD" || b.is_empty() => None,
        Ok(b) => Some(b),
        Err(_) => None,
    }
}
